let mainClickProbe = { attempted: true, hit: false, error: null };
try { await app.click([160, 300]); mainClickProbe.hit = true; } catch (e) { mainClickProbe.error = String((e && e.message) || e); }
let mainClickState = await app.getAXState(); nodeRepl.write(JSON.stringify(mainClickProbe)); nodeRepl.write(mainClickState);

let menuProbe = { attempted: true, label: "View", opened: false, error: null };
try { await app.click(50); } catch (e) { menuProbe.error = String((e && e.message) || e); }
let menuState = await app.getAXStateAndScreenshot({ disableDiffing: true });
nodeRepl.write(JSON.stringify(menuProbe));
nodeRepl.write(menuState.state);
await nodeRepl.emitImage(menuState.screenshot);

menuProbe.opened = true;
await app.pressKey("Escape");
let shortcutProbe = { attempted: true, keys: "cmd+f", delivered: false, error: null };
try { await app.pressKey("cmd+f"); shortcutProbe.delivered = true; } catch (e) { shortcutProbe.error = String((e && e.message) || e); }
let shortcutState = await app.getAXStateAndScreenshot({ disableDiffing: true });
nodeRepl.write(JSON.stringify(menuProbe));
nodeRepl.write(JSON.stringify(shortcutProbe));
nodeRepl.write(shortcutState.state);
await nodeRepl.emitImage(shortcutState.screenshot);

let closeMenuError = null;
try { await app.performSecondaryAction(0, "Cancel"); } catch (e) { closeMenuError = String((e && e.message) || e); }
let closedState = await app.getAXState({ disableDiffing: true });
nodeRepl.write(JSON.stringify({closeMenuError}));
nodeRepl.write(closedState);

let chooseError = null;
try { await app.click(14); } catch (e) { chooseError = String((e && e.message) || e); }
let afterChoose = await app.getAXState({ disableDiffing: true });
nodeRepl.write(JSON.stringify({chooseError}));
nodeRepl.write(afterChoose);

