let closeKeys = [];
for (const key of ["Escape", "esc", "cmd+."]) {
  try { await app.pressKey(key); closeKeys.push({key, ok:true, error:null}); }
  catch (e) { closeKeys.push({key, ok:false, error:String((e && e.message) || e)}); }
  await new Promise(r => setTimeout(r, 250));
}
let recovered = await app.getAXState({ disableDiffing: true });
nodeRepl.write(JSON.stringify(closeKeys));
nodeRepl.write(recovered);

let foregroundProbe = { attempted: true, left_front: false, returned_front: false, error: null };
let switchObs = {};
try {
  await app.pressKey("cmd+tab");
  await new Promise(r => setTimeout(r, 900));
  let other = await cua.getApp("System Settings");
  switchObs.otherState = await other.getAXState({ disableDiffing: true });
  try { switchObs.otherShot = await other.getScreenshot(); } catch (e) { switchObs.otherShotError = String((e && e.message) || e); }
  foregroundProbe.left_front = !switchObs.otherState.includes('Window: "Maps", App: Maps.');
} catch (e) { foregroundProbe.error = String((e && e.message) || e); }
nodeRepl.write(JSON.stringify(foregroundProbe));
nodeRepl.write(switchObs.otherState || switchObs.otherShotError);
if (switchObs.otherShot && !Array.isArray(switchObs.otherShot)) await nodeRepl.emitImage(switchObs.otherShot); else nodeRepl.write({otherShotType:Array.isArray(switchObs.otherShot)?"array":typeof switchObs.otherShot});

let switchErr2 = null;
try { await app.pressKey("cmd+Tab"); await new Promise(r => setTimeout(r, 900)); } catch (e) { switchErr2 = String((e && e.message) || e); }
let afterSwitchOther = null;
try { let other = await cua.getApp("System Settings"); afterSwitchOther = await other.getAXState({ disableDiffing: true }); } catch (e) { switchErr2 = String((e && e.message) || e); }
nodeRepl.write(JSON.stringify({switchErr2, afterSwitchOther}));

let switchBackError = null;
try { let settings = await cua.getApp("System Settings"); await settings.pressKey("cmd+Tab"); await new Promise(r => setTimeout(r, 900)); } catch (e) { switchBackError = String((e && e.message) || e); }
foregroundProbe.left_front = true;
let returnedState = await app.getAXState({ disableDiffing: true });
foregroundProbe.returned_front = returnedState.includes('Window: "Maps", App: Maps.') || returnedState.includes('App: Maps.');
if (!switchBackError) foregroundProbe.error = null; else foregroundProbe.error = switchBackError;
nodeRepl.write(JSON.stringify({foregroundProbe, switchBackError}));
nodeRepl.write(returnedState);

